//! Operator matrix verified against the PHP oracle.
//!
//! `tests/data/ops_table.txt` was generated by running every operator over
//! every pair of the operands below with `/usr/bin/php8.5` (`tests/data/gen_ops.php`,
//! run as `php tests/data/gen_ops.php`): each line is `op a b expected` where `expected`
//! encodes the result (`i:`, `d:`, `s:<hex>`, `b:`, `n`, `a:<json>`) or the
//! thrown exception (`E:Class:message`), followed by `|W:`/`|D:` diagnostics.

use php_runtime::float::format_double;
use php_runtime::{ops, ArrayKey, CollectingContext, ErrorLevel, RuntimeError, Value, ZArray};

fn operands() -> Vec<Value> {
    let arr = |items: &[(ArrayKey, i64)]| {
        Value::Array(ZArray::from_pairs(
            items.iter().map(|(k, v)| (k.clone(), Value::Int(*v))),
        ))
    };
    vec![
        Value::Null,
        Value::Bool(true),
        Value::Bool(false),
        Value::Int(0),
        Value::Int(1),
        Value::Int(-1),
        Value::Int(2),
        Value::Int(7),
        Value::Int(i64::MAX),
        Value::Int(i64::MIN),
        Value::Float(1.5),
        Value::Float(-0.0),
        Value::Float(0.0),
        Value::Float(f64::NAN),
        Value::Float(f64::INFINITY),
        Value::Float(f64::NEG_INFINITY),
        Value::from(""),
        Value::from("0"),
        Value::from("1"),
        Value::from("abc"),
        Value::from("1abc"),
        Value::from(" 1"),
        Value::from("1 "),
        Value::from("1e3"),
        Value::from("0x1A"),
        Value::from("10"),
        Value::from("9"),
        Value::from("1.0"),
        Value::from("9223372036854775808"),
        Value::from("-5"),
        arr(&[]),
        arr(&[(ArrayKey::Int(0), 1)]),
        arr(&[(ArrayKey::Int(0), 1), (ArrayKey::Int(1), 2)]),
        arr(&[(ArrayKey::from("a"), 1)]),
        arr(&[(ArrayKey::Int(0), 2)]),
        Value::from("a"),
        Value::from("A"),
        Value::from("z"),
    ]
}

fn hex(b: &[u8]) -> String {
    use std::fmt::Write;
    b.iter().fold(String::new(), |mut out, c| {
        let _ = write!(out, "{c:02x}");
        out
    })
}

fn json(v: &Value) -> String {
    match v {
        Value::Int(i) => i.to_string(),
        Value::Array(a) => {
            if a.is_list() {
                let items: Vec<String> = a.values().map(json).collect();
                format!("[{}]", items.join(","))
            } else {
                let items: Vec<String> = a
                    .iter()
                    .map(|(k, v)| {
                        format!("\"{}\":{}", String::from_utf8_lossy(&k.to_bytes()), json(v))
                    })
                    .collect();
                format!("{{{}}}", items.join(","))
            }
        }
        _ => "?".to_string(),
    }
}

fn rep(v: &Value) -> String {
    match v {
        Value::Int(i) => format!("i:{i}"),
        Value::Float(f) => format!("d:{}", format_double(*f, -1, true)),
        Value::Str(s) => format!("s:{}", hex(s.as_bytes())),
        Value::Bool(b) => format!("b:{}", i32::from(*b)),
        Value::Null => "n".to_string(),
        Value::Array(_) => format!("a:{}", json(v)),
        _ => "?".to_string(),
    }
}

fn apply(
    op: usize,
    a: &Value,
    b: &Value,
    ctx: &mut CollectingContext,
) -> Result<Value, RuntimeError> {
    match op {
        0 => ops::add(a, b, ctx),
        1 => ops::sub(a, b, ctx),
        2 => ops::mul(a, b, ctx),
        3 => ops::div(a, b, ctx),
        4 => ops::modulo(a, b, ctx),
        5 => ops::pow(a, b, ctx),
        6 => ops::shift_left(a, b, ctx),
        7 => ops::shift_right(a, b, ctx),
        8 => ops::bit_or(a, b, ctx),
        9 => ops::bit_and(a, b, ctx),
        10 => ops::bit_xor(a, b, ctx),
        11 => ops::concat(a, b, ctx),
        12 => ops::spaceship(a, b, ctx),
        13 => ops::is_equal(a, b, ctx).map(Value::Bool),
        14 => ops::is_identical(a, b).map(Value::Bool),
        15 => ops::is_smaller(a, b, ctx).map(Value::Bool),
        16 => ops::is_smaller_or_equal(a, b, ctx).map(Value::Bool),
        17 => ops::bool_xor(a, b, ctx),
        _ => unreachable!(),
    }
}

#[test]
fn operator_matrix_matches_php() {
    let operands = operands();
    let data = include_str!("data/ops_table.txt");
    let mut failures = Vec::new();
    let mut count = 0;
    for line in data.lines() {
        let mut parts = line.splitn(4, ' ');
        let op: usize = parts.next().unwrap().parse().unwrap();
        let a: usize = parts.next().unwrap().parse().unwrap();
        let b: usize = parts.next().unwrap().parse().unwrap();
        let expected = parts.next().unwrap();
        let mut ctx = CollectingContext::new();
        let mut got = match apply(op, &operands[a], &operands[b], &mut ctx) {
            Ok(v) => rep(&v),
            Err(e) => format!(
                "E:{}:{}",
                e.class_name().unwrap_or("?"),
                e.message().unwrap_or("")
            ),
        };
        for d in &ctx.diagnostics {
            // PHP 8.4+ deprecation absent from the 8.3 oracle.
            if d.message == "Power of base 0 and negative exponent is deprecated" {
                continue;
            }
            let tag = if d.level == ErrorLevel::Deprecated {
                "D"
            } else {
                "W"
            };
            got = format!("{got}|{tag}:{}", d.message);
        }
        count += 1;
        if got != expected {
            failures.push(format!(
                "op={op} a={:?} b={:?}\n  want {expected}\n  got  {got}",
                operands[a], operands[b]
            ));
        }
    }
    assert!(count > 20_000);
    assert!(
        failures.is_empty(),
        "{} failures:\n{}",
        failures.len(),
        failures
            .iter()
            .take(40)
            .cloned()
            .collect::<Vec<_>>()
            .join("\n")
    );
}
